=== src/db.ts
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

/** Opens the SQLite database shared by the server and worker processes. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  return db;
}
=== src/server.ts
import { createServer, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';

// Starting point. See TASK.md for the required behaviour.
const db = openDatabase();
void db;
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

const port = Number(process.env.PORT ?? 3000);
createServer((req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/health' && req.method === 'GET') {
    return send(res, 200, { status: 'ok', worker: 'down' });
  }
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  send(res, 501, { error: { code: 'not_implemented', message: 'Not implemented yet.' } });
}).listen(port, () => console.log(`server listening on ${port}`));
=== src/worker.ts
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

// Starting point. See TASK.md for the required behaviour.
const db = openDatabase();
void db;
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

console.log('worker started');
while (!stopping) {
  await sleep(100);
}
