    async run(ctx) {
      const input = 'Check example';
      const job = await create(ctx, { input, steps: 2 });
      expectQueuedJob(job, input, 2, 0, 'created job');
      const id = jobId(job, 'created job');
      expectEqual((await getJob(ctx, id)).id, id, `GET /api/jobs/${id} id`);
