export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type Validation =
  | { ok: true; value: Submission; key: string | undefined }
  | { ok: false; fields: FieldError[] };

const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JSON_CONTENT_TYPE = /^application\/json\s*(;.*)?$/i;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

export interface RawSubmission {
  contentType: string | undefined;
  body: string;
  bodyTooLarge: boolean;
  idempotencyKey: string | undefined;
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function integerIn(v: unknown, min: number, max: number): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

/** Validates a POST /api/jobs request. Defaults are applied to optional numeric fields. */
export function validateSubmission(raw: RawSubmission): Validation {
  const fields: FieldError[] = [];
  let key: string | undefined;
  if (raw.idempotencyKey !== undefined) {
    if (KEY_RE.test(raw.idempotencyKey)) key = raw.idempotencyKey;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let value: Submission | undefined;
  if (raw.bodyTooLarge) {
    fields.push({ field: 'body', message: 'request body is too large' });
  } else if (!raw.contentType || !JSON_CONTENT_TYPE.test(raw.contentType.trim())) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw.body);
    } catch {
      parsed = undefined;
      fields.push({ field: 'body', message: 'body is not valid JSON' });
    }
    if (parsed !== undefined) {
      if (!isPlainObject(parsed)) fields.push({ field: 'body', message: 'body must be a JSON object' });
      else value = validateFields(parsed, fields);
    }
  }

  if (fields.length > 0 || value === undefined) return { ok: false, fields };
  return { ok: true, value, key };
}

function validateFields(obj: Record<string, unknown>, fields: FieldError[]): Submission | undefined {
  for (const k of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(k)) fields.push({ field: k, message: 'unknown field' });
  }

  const { input, steps = 5, failAttempts = 0 } = obj as Record<string, unknown>;
  let ok = true;

  if (input === undefined) {
    fields.push({ field: 'input', message: 'is required' });
    ok = false;
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
    ok = false;
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
    ok = false;
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
    ok = false;
  }

  if (!integerIn(steps, 1, 20)) {
    fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
    ok = false;
  }
  if (!integerIn(failAttempts, 0, 5)) {
    fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
    ok = false;
  }

  if (!ok) return undefined;
  return { input: input as string, steps: steps as number, failAttempts: failAttempts as number };
